    /**
     * One 960-unit Material Symbols glyph. [shifted] paths are drawn in the web font's `0 -960 960 960`
     * box, which Android's drawables move back into view with a 960-unit `translateY`.
     */
    private fun symbol(name: String, path: String, shifted: Boolean = false, autoMirror: Boolean = false): ImageVector =
        ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f, autoMirror = autoMirror)
            .group(translationY = if (shifted) 960f else 0f) {
                addPath(addPathNodes(path), fill = SolidColor(Color.Black))
            }.build()
}
